#!/data/data/com.termux/files/usr/bin/bash
# Install a Termux:Boot script so the app comes back after a device reboot.
#
# Requires the Termux:Boot app (F-Droid). Without it the hook is still written
# to ~/.termux/boot/ and will run once Termux:Boot is installed.

set -uo pipefail

PROJECT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BOOT_DIR="$HOME/.termux/boot"
BOOT_SCRIPT="$BOOT_DIR/hermes-miniapp.sh"

mkdir -p "$BOOT_DIR"

cat > "$BOOT_SCRIPT" <<EOF
#!/data/data/com.termux/files/usr/bin/bash
# Auto-generated by hermes_bot_miniapp/scripts/install_boot.sh
termux-wake-lock
sleep 20
cd "$PROJECT_DIR" || exit 1
bash scripts/start.sh >> logs/boot.out 2>&1
bash scripts/run_bot.sh >> logs/boot.out 2>&1 &
EOF

chmod +x "$BOOT_SCRIPT"
echo "✓ installed $BOOT_SCRIPT"
echo
if [ -d "/data/data/com.termux/files/home/.termux" ]; then
  echo "Termux:Boot hook written. To activate:"
  echo "  1. Install the Termux:Boot app from F-Droid"
  echo "  2. Open it once (grants the BOOT_COMPLETED permission)"
  echo "  3. Reboot — the app will start automatically"
else
  echo "⚠ ~/.termux not found; is this Termux?"
fi
echo
echo "Manual start after reboot:"
echo "  cd $PROJECT_DIR && bash scripts/start.sh && bash scripts/run_bot.sh"
